#!/bin/bash -e

# The release notes generated by GitHub (sorted by the release labels of the pull requests, see
# .github/release.yml), with the diff of the layer if it changed since the previous release.
#
# tests/release_notes.sh <tag>: add them to the release of <tag> (below what was written by hand), if they
# weren't already, or the release draft keeps them up to date (see tests/release_draft.sh).
# With DRY_RUN=1, prints the new body of the release instead.
#
# Sourced (by tests/release_draft.sh), defines release_notes <tag> <target> [<previous tag>], printing them.
#
# Needs GITHUB_TOKEN (able to edit the releases) and the tags.

# Fail on errors in pipes and in $(...) too (bash 4.4+): a missing diff must not go unnoticed.
set -o pipefail
shopt -s inherit_errexit 2> /dev/null || true

RELEASE_NOTES_MARKER='<!-- release-notes -->'
LAYER_DIFF_MARKER='<!-- layer-diff -->'

layer()
{
    git show "$1:src/Settings/TLSchema.php" | grep -m1 -o 'layer = [0-9]\+' | grep -o '[0-9]\+'
}

release_notes()
{
    local tag=$1 target=$2 previous=${3:-} repository=${GH_REPO:-danog/MadelineProto}
    local generated
    generated=$(gh api -X POST "repos/$repository/releases/generate-notes" -f tag_name="$tag" -f target_commitish="$target" ${previous:+-f previous_tag_name="$previous"} --jq .body)
    # The tag GitHub compared with, from the link to the full changelog.
    if [ "$previous" == "" ]; then
        previous=$( (grep -m1 -o "compare/[^ ]*\.\.\.$tag" <<< "$generated" || true) | sed -E 's|compare/(.*)\.\.\..*|\1|')
    fi
    printf '%s\n%s\n' "$RELEASE_NOTES_MARKER" "$generated"
    if [ "$previous" == "" ]; then
        return
    fi
    git fetch -q --tags origin
    local ref=$tag old new diff
    if ! git rev-parse -q --verify "refs/tags/$tag" > /dev/null; then
        ref=$target
    fi
    old=$(layer "$previous")
    new=$(layer "$ref")
    if [ "$old" != "$new" ]; then
        git submodule update --init schemas
        diff=$(php tools/layerdiff.php --no-send "$old" "$new")
        printf '\n%s\n## Layer %s\n\nChanges since layer %s:\n\n' "$LAYER_DIFF_MARKER" "$new" "$old"
        # Without what the logger prints before it.
        sed -n '/^New /,$p' <<< "$diff"
    fi
}

if [ "${BASH_SOURCE[0]}" != "$0" ]; then
    return 0
fi

tag=$1
repository=${GH_REPO:-danog/MadelineProto}
export GH_TOKEN="${GH_TOKEN:-$GITHUB_TOKEN}"

body=$(gh api "repos/$repository/releases/tags/$tag" --jq .body)
if [[ "$body" == *"$RELEASE_NOTES_MARKER"* ]] && [ -z "$DRY_RUN" ]; then
    echo "The release notes of $tag were already generated"
    exit 0
fi

notes=$(mktemp)
{
    if [ "$body" != "" ]; then
        printf '%s\n\n' "${body%%"$RELEASE_NOTES_MARKER"*}"
    fi
    release_notes "$tag" "$tag"
} > "$notes"
if [ -n "$DRY_RUN" ]; then
    cat "$notes"
    rm "$notes"
    exit 0
fi
gh release edit "$tag" --repo "$repository" --notes-file "$notes"
rm "$notes"
echo "Added the release notes of $tag"
